import json,html
from collections import Counter
from urllib.parse import quote

def write_reports(out,items,coverage,metadata):
    def dump(name,obj): (out/name).write_text(json.dumps(obj,indent=2,ensure_ascii=True))
    dump('findings.json',items);dump('coverage.json',coverage);dump('metadata.json',metadata)
    rules=sorted({f['rule'] for f in items})
    sarif={'$schema':'https://json.schemastore.org/sarif-2.1.0.json','version':'2.1.0','runs':[{'tool':{'driver':{'name':'mobile-audit','version':'0.1.0','rules':[{'id':r} for r in rules]}},'results':[{'ruleId':f['rule'],'level':{'critical':'error','high':'error','medium':'warning','low':'note'}.get(f['severity'],'note'),'message':{'text':f['title']+' '+f['validation_status']},'locations':[{'physicalLocation':{'artifactLocation':{'uri':quote(f['file'],safe='/')},'region':{'startLine':f['line'],'endLine':f['end_line']}}}],'partialFingerprints':{'mobileAuditId':f['id']},'properties':{'classification':f['classification'],'confidence':f['confidence']}} for f in items]}]}
    dump('findings.sarif',sarif)
    counts=dict(Counter(f['severity'] for f in items));categories=dict(Counter(f['cwe'] or 'Unclassified' for f in items))
    md=['# Mobile source security audit',f"Repository: {metadata['repository']}",f"Time: {metadata['timestamp']}",'## Executive summary',f'{len(items)} candidate findings. Severity counts: {counts}. Categories: {categories}.','Risk assessment: prioritize high-severity candidates; static matches do not establish exploitability. A clean result is not assurance of security.','## Findings']
    for f in items:
        md.extend([f"### {f['id']} — {f['title']}",f"{f['severity']} | {f['cwe'] or 'CWE not assigned'} | {f['file']}:{f['line']}-{f['end_line']}",f"Classification: {f['classification']}",f"Detection: {', '.join(f['detection_source'])} | Confidence: {f['confidence']}",f"Validation: {f['validation_status']}",'```',f['evidence'],'```',f['explanation'],'Attack prerequisites: '+f['attack_prerequisites'],'Potential impact: '+f['impact'],'Remediation: '+f['remediation'],'Independent review: '+json.dumps(f.get('independent_review','Not reviewed'))])
    md.extend(['## Coverage and limitations','```json',json.dumps(coverage,indent=2),'```','## Tools and model configuration','```json',json.dumps(metadata,indent=2),'```'])
    (out/'report.md').write_text('\n\n'.join(md))
    esc=lambda v:html.escape(str(v))
    cards=[]
    for f in items:
        fields=''.join('<dt>'+esc(k.replace('_',' ').title())+'</dt><dd>'+esc(f.get(k,''))+'</dd>' for k in ['classification','confidence','validation_status','explanation','attack_prerequisites','impact','remediation','additional_observations'])
        cards.append('<article id="'+esc(f['id'])+'"><h2><span class="badge '+esc(f['severity'])+'">'+esc(f['severity'].upper())+'</span> '+esc(f['title'])+'</h2><p>'+esc(f['id'])+' · '+esc(f['cwe'] or 'CWE unassigned')+' · '+esc(f['file'])+':'+str(f['line'])+'–'+str(f['end_line'])+'</p><p>Detected by '+esc(', '.join(f['detection_source']))+'</p><pre>'+esc(f['evidence'])+'</pre><dl>'+fields+'</dl><details><summary>Independent review</summary><pre>'+esc(json.dumps(f.get('independent_review','Not reviewed'),indent=2))+'</pre></details></article>')
    rows=''.join('<tr><td>'+esc(c['name'])+'</td><td>'+esc(c['status'])+'</td><td>'+esc(c.get('version',''))+'</td><td>'+esc('; '.join(c.get('errors',[])))+'</td></tr>' for c in coverage.get('checks',[]))
    body='<header><p>LOCAL SOURCE SECURITY ASSESSMENT</p><h1>Mobile application security audit</h1><p>'+esc(metadata['repository'])+' · '+esc(metadata['timestamp'])+'</p></header><section><h2>Executive summary</h2><p>'+str(len(items))+' candidate findings. Scanner matches and AI hypotheses require exploitability review.</p><p>Severity: '+esc(counts)+'</p><p>Categories: '+esc(categories)+'</p><p>Overall risk: review high-severity candidates first. Incomplete checks and budgeted AI investigation limit assurance.</p></section><section><h2>Scanner and model coverage</h2><table><tr><th>Check</th><th>Status</th><th>Version</th><th>Limitations / errors</th></tr>'+rows+'</table></section>'+''.join(cards)+'<section><h2>Coverage and analysis limitations</h2><pre>'+esc(json.dumps(coverage,indent=2))+'</pre><h2>Execution metadata</h2><pre>'+esc(json.dumps(metadata,indent=2))+'</pre></section>'
    css="body{font:15px/1.6 system-ui;max-width:1120px;margin:0 auto;padding:36px 22px;color:#183044;background:#eef3f7}header{background:#142f46;color:white;padding:28px;border-radius:12px}h1{font-size:32px}h2{font-size:21px}article,section{background:white;padding:24px;margin:24px 0;border-radius:10px;box-shadow:0 2px 8px #1231}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f1f5f8;padding:16px;border-radius:6px;font:13px/1.6 ui-monospace,monospace}dt{font-weight:650;margin-top:10px}dd{margin-left:0}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;padding:10px;border-bottom:1px solid #ddd;overflow-wrap:anywhere}.badge{font-size:11px;padding:5px 8px;border-radius:5px;background:#dfebf5}.high,.critical{background:#ffe0e0;color:#a21b24}.medium{background:#fff1ca;color:#805900}@media print{body{background:white}article{break-inside:avoid}}"
    (out/'report.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'"><title>Mobile source security audit</title><style>'+css+'</style><body>'+body+'</body></html>')
